// Environment configuration for GhostGram Extension
// This file is automatically generated based on the environment

// Import type definitions
import GhostGramConfig from './types.js';

// Load environment variables from .env file
import { config as loadEnv } from 'dotenv';
loadEnv();

// Get environment variables
const _API_BASE_URL = process.env.API_BASE_URL || 'https://api.ghostgram.com';
const LOCAL_API_BASE_URL = process.env.LOCAL_API_BASE_URL || 'http://localhost:3001';
const ENABLE_DEBUG = process.env.ENABLE_DEBUG === 'true';
const ENABLE_DEV_TOOLS = process.env.ENABLE_DEV_TOOLS === 'true';
const ENABLE_LOCAL_API = process.env.ENABLE_LOCAL_API === 'true';
const DEVELOPMENT_MODE = process.env.DEVELOPMENT_MODE === 'true';
const IS_LOCAL_DEVELOPMENT = process.env.IS_LOCAL_DEVELOPMENT === 'true';
const IS_LOCAL_API = process.env.IS_LOCAL_API === 'true';

// Check if we're running in a local development environment
// In a browser context, we'll check for a global configuration object
const isLocalDevelopment = DEVELOPMENT_MODE || IS_LOCAL_DEVELOPMENT || typeof window !== 'undefined' && (window as any).ghostgramConfig?.development === true;
const _isLocalApi = ENABLE_LOCAL_API || IS_LOCAL_API || typeof window !== 'undefined' && (window as any).ghostgramConfig?.localApi === true;

// Base API URL configuration
export const API_BASE_URL = _isLocalApi ? LOCAL_API_BASE_URL : _API_BASE_URL;

// API endpoints
export const API_ENDPOINTS = {
  login: `${API_BASE_URL}/auth/login`,
  logout: `${API_BASE_URL}/auth/logout`,
  scan: `${API_BASE_URL}/scans`,
  history: `${API_BASE_URL}/history`,
  whitelist: `${API_BASE_URL}/whitelist`,
  users: `${API_BASE_URL}/users`,
  billing: `${API_BASE_URL}/billing`,
  health: `${API_BASE_URL}/health`
};

// Feature flags
export const FEATURE_FLAGS = {
  // Development mode
  development: isLocalDevelopment || _isLocalApi,

  // Local API mode
  localApi: _isLocalApi,

  // Debug mode
  debug: ENABLE_DEBUG || isLocalDevelopment || _isLocalApi,

  // Development tools
  devTools: ENABLE_DEV_TOOLS || isLocalDevelopment || _isLocalApi,

  // Debug logging
  debugLogging: ENABLE_DEBUG || isLocalDevelopment || _isLocalApi
};

// Timeout configurations (in milliseconds)
export const TIMEOUTS = {
  api: _isLocalApi ? 10000 : parseInt(process.env.API_TIMEOUT || '15000'),
  instagram: parseInt(process.env.INSTAGRAM_TIMEOUT || '15000'),
  storage: parseInt(process.env.STORAGE_TIMEOUT || '5000')
};

// Retry configurations
export const RETRY_CONFIG = {
  maxAttempts: parseInt(process.env.MAX_RETRY_ATTEMPTS || '3'),
  delay: parseInt(process.env.RETRY_DELAY || '1000'),
  backoff: parseFloat(process.env.RETRY_BACKOFF || '2') // Exponential backoff factor
};

// Logging configuration
export const LOGGING = {
  level: process.env.LOG_LEVEL || (isLocalDevelopment || _isLocalApi ? 'debug' : 'info'),
  enabled: ENABLE_DEBUG || isLocalDevelopment || _isLocalApi
};

// Export for use in the extension
export const ENVIRONMENT_CONFIG = {
  API_BASE_URL,
  API_ENDPOINTS,
  FEATURE_FLAGS,
  TIMEOUTS,
  RETRY_CONFIG,
  LOGGING
};

// Convenience exports
export const {
  API_BASE_URL: baseUrl,
  API_ENDPOINTS: endpoints,
  FEATURE_FLAGS: features,
  TIMEOUTS: timeouts,
  RETRY_CONFIG: retry,
  LOGGING: logging
} = ENVIRONMENT_CONFIG;

// Default export
export default ENVIRONMENT_CONFIG;

// Runtime check for development mode
export const isDevelopment = () => {
  return FEATURE_FLAGS.development;
};

export const isLocalApi = () => {
  return FEATURE_FLAGS.localApi;
};